INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7562915, 1212549, 184608, '<td valign="top">Nice Light!</td>', 'Nice Light!', '2018-03-16 20:02:39.000000', NULL, 1),
(7562916, 1212782, 184608, '<td valign="top">As a year long Bike Commuter I appreciate this. nice composition too.</td>', 'As a year long Bike Commuter I appreciate this. nice composition too.', '2018-03-16 20:03:59.000000', NULL, 1),
(7562917, 1212892, 184608, '<td valign="top">love the B&amp;W processing. I think the drastic crop of the wide lens is throwing me off</td>', 'love the B&W processing. I think the drastic crop of the wide lens is throwing me off', '2018-03-16 20:05:55.000000', NULL, 1),
(7563455, 1212877, 103410, '<td valign="top">very good depth of field</td>', 'very good depth of field', '2018-03-21 07:26:52.000000', NULL, 1),
(7563480, 1212782, 138630, '<td valign="top">Really like this one.  This is the kind of image I imagined - a subject for which I have a clear notion of appropriate season (bikes), equally clearly out of place in terms of an indication of season (heavy snow).  Plus I like the angle and composition though for me it would flow better if you gave it a horizontal flip.</td>', 'Really like this one.  This is the kind of image I imagined - a subject for which I have a clear notion of appropriate season (bikes), equally clearly out of place in terms of an indication of season (heavy snow).  Plus I like the angle and composition though for me it would flow better if you gave it a horizontal flip.', '2018-03-21 11:23:44.000000', NULL, 1),
(7563481, 1212618, 138630, '<td valign="top">This is a hoot and such a perfect fit for the theme - what on earth is this guy thinking?  Obviously, "Gotta go take my morning dip" . . . or maybe there''s a sauna down there??  I just wish the light on the houses and him had been better . . . and I would lose half the space between him and the bottom to move him down in the frame.  8 for a great theme fit.</td>', 'This is a hoot and such a perfect fit for the theme - what on earth is this guy thinking?  Obviously, "Gotta go take my morning dip" . . . or maybe there''s a sauna down there??  I just wish the light on the houses and him had been better . . . and I would lose half the space between him and the bottom to move him down in the frame.  8 for a great theme fit.', '2018-03-21 11:26:56.000000', NULL, 1),
(7563482, 1212760, 138630, '<td valign="top">Here''s another excellent theme fit IMO.  I like the composition and the kind of dark hole they are peeking out of.  Wish I could see just a few daffodil leaves - I think this is real, but I''d like more "proof" :)  8</td>', 'Here''s another excellent theme fit IMO.  I like the composition and the kind of dark hole they are peeking out of.  Wish I could see just a few daffodil leaves - I think this is real, but I''d like more "proof" :)  8', '2018-03-21 11:30:19.000000', NULL, 1),
(7563483, 1212748, 138630, '<td valign="top">Like this subject a lot.  Am not that crazy about the angle or the processing though the angle certainly does show off the boots as planters, emphasizing the juxtaposition of two seasons; and the processing suits the subject, too . . . not sure why it doesn''t quite work for me.  Maybe too yellow.</td>', 'Like this subject a lot.  Am not that crazy about the angle or the processing though the angle certainly does show off the boots as planters, emphasizing the juxtaposition of two seasons; and the processing suits the subject, too . . . not sure why it doesn''t quite work for me.  Maybe too yellow.', '2018-03-21 11:53:32.000000', NULL, 1),
(7563575, 1212687, 38032, '<td valign="top">can''t help but love that well-shot contour.</td>', 'can''t help but love that well-shot contour.', '2018-03-21 23:25:03.000000', NULL, 1),
(7563577, 1212782, 38032, '<td valign="top">Bikes covered in snow  yes I love them so much. Very well shot. 8</td>', 'Bikes covered in snow  yes I love them so much. Very well shot. 8', '2018-03-21 23:26:02.000000', NULL, 1),
